/**
 * Corrupt transport must never masquerade as valid syntax. These fixtures are
 * independent malformed responses, not copies generated by the bridge encoder.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { InputError, parseSync } from '../src/syntax.js';
import { ShInternalError } from '../src/errors.js';
import { callSyntax } from '../src/wasm-instance.js';
import { decodeWire, encodeWire, isSyntaxNode } from '../src/syntax-wire.js';

vi.mock('../src/wasm-instance.js', () => ({ callSyntax: vi.fn() }));

beforeEach(() => vi.resetAllMocks());

describe('syntax response integrity', () => {
  it.each(['null', '[]', '{}', '{', '{"File":{"Type":"File"}}'])(
    'rejects malformed response %s',
    (raw) => {
      vi.mocked(callSyntax).mockReturnValue(raw);
      expect(() => parseSync('')).toThrow(ShInternalError);
    },
  );

  it('rejects impossible recovered and valid position flags', () => {
    vi.mocked(callSyntax).mockReturnValue(
      JSON.stringify({
        File: {
          Type: 'File',
          Name: '',
          Stmts: null,
          Last: [
            {
              Type: 'Comment',
              Text: 'x',
              Hash: {
                Offset: 0,
                Line: 1,
                Col: 1,
                IsValid: true,
                IsRecovered: true,
                OffsetOverflow: true,
              },
            },
          ],
        },
      }),
    );
    expect(() => parseSync('#x')).toThrow(ShInternalError);
  });

  it('does not interpret inherited object property names as syntax types', () => {
    vi.mocked(callSyntax).mockReturnValue('{"File":{"Type":"toString"}}');
    expect(() => parseSync('')).toThrow(ShInternalError);
  });
});

describe('exact byte and integer adaptation', () => {
  it('round-trips invalid UTF-8 bytes without interpreting them as text', () => {
    const bytes = new Uint8Array([0xff, 0, 0x80]);
    expect(decodeWire(encodeWire({ Value: bytes }))).toEqual({ Value: bytes });
    expect(encodeWire(2n ** 63n - 1n)).toBe('{"Int":"9223372036854775807"}');
  });

  it('rejects malformed base64 rather than silently truncating bytes', () => {
    expect(() => decodeWire('{"Bytes":"invalid!!!"}')).toThrow(ShInternalError);
  });

  it('rejects cycles and values JSON would silently omit or replace', () => {
    const cyclic: { self?: unknown } = {};
    cyclic.self = cyclic;
    expect(() => encodeWire(cyclic)).toThrow(InputError);
    expect(() => encodeWire({ absent: undefined })).toThrow(InputError);
    expect(() => encodeWire({ value: NaN })).toThrow(InputError);
    expect(() => encodeWire('\ud800')).toThrow(InputError);
  });
});

/** A dynamic nil pointer retains its concrete Go interface type, unlike null. */
describe('typed nil interface values', () => {
  it('recognizes exact tags for Node implementers only', () => {
    expect(isSyntaxNode({ Type: 'TypedNil', Kind: 'Word' })).toBe(true);
    expect(isSyntaxNode({ Type: 'TypedNil', Kind: 'Slice' })).toBe(false);
    expect(isSyntaxNode({ Type: 'TypedNil', Kind: 'toString' })).toBe(false);
    expect(isSyntaxNode({ Type: 'TypedNil', Kind: 'Word', Value: '' })).toBe(false);
  });
});
